if (!_is2) throw new Error("data/canon.js must load before ot-25-isaiah-b.js");
(_is2.chapters = _is2.chapters || []).push(
  { n:23, summary:"The burden of Tyre opens with merchants howling: ships of Tarshish wail because the port lies waste, with no house and no way in. Zidon is ashamed, and the sea speaks as a barren mother who has brought up no children. The chapter asks who could silence so joyous a city, whose merchants were princes and traffickers the honourable of the earth, and answers that the LORD of hosts has purposed it, to stain the pride of all glory. Tyre is pictured as an oppressed virgin sent wandering to Chittim with no rest, while the rising land of the Chaldeans will bring her to ruin. She shall be forgotten seventy years, then sing as an harlot for hire again; yet at last her merchandise becomes holiness to the LORD, food and durable clothing for them that dwell before him.",
    context:"An oracle against Tyre, the ancient Phoenician merchant city, foretelling its fall, seventy forgotten years, and a final dedication of its trade to the LORD.",
    keyVerses:[
      { ref:"Isaiah 23:9", text:"The LORD of hosts hath purposed it, to stain the pride of all glory, and to bring into contempt all the honourable of the earth." },
      { ref:"Isaiah 23:15", text:"And it shall come to pass in that day, that Tyre shall be forgotten seventy years, according to the days of one king: after the end of seventy years shall Tyre sing as an harlot." },
      { ref:"Isaiah 23:18", text:"And her merchandise and her hire shall be holiness to the LORD: it shall not be treasured nor laid up; for her merchandise shall be for them that dwell before the LORD, to eat sufficiently, and for durable clothing." }
    ],
    takeaway:"The LORD stains the pride of all glory; even a merchant city's wealth can end in holiness or emptiness.",
    quiz:[
      { q:"Whose ships howl at the news that Tyre is laid waste?", choices:["The ships of Tarshish","The fleets of Egypt","The navy of Chittim","The sailors of Sihor"], a:0, why:"Verse 1 opens, Howl, ye ships of Tarshish; for it is laid waste. The repeated cry returns in verse 14." },
      { q:"Why does the LORD bring Tyre low, according to the chapter?", choices:["To punish her for refusing to trade with Tarshish","To stain the pride of all glory and bring into contempt the honourable of the earth","Because she allied herself with Babylon against Assyria","Because her harbors had silted up over time"], a:1, why:"Verse 9 answers the question of verse 8: the LORD of hosts hath purposed it, to stain the pride of all glory." },
      { q:"What does Tyre's final fate — her merchandise becoming holiness to the LORD — teach about wealth?", choices:["Commerce is evil and must be abandoned","Earthly trade ends, but God can turn even its profit to holy purposes","Money lasts longer than prophecy","Wealth is a sign of God's constant favor"], a:2, why:"Verse 18 says her merchandise shall be for them that dwell before the LORD, to eat sufficiently, and for durable clothing." }
    ] },
  { n:24, summary:"Isaiah watches the LORD make the earth empty, waste, and turned upside down, scattering its inhabitants. The judgment levels every rank: as with the people, so with the priest; buyer with seller, lender with borrower. The ground is defiled because its people transgressed the laws, changed the ordinance, and broke the everlasting covenant, so the curse devours the earth and few men are left. Every celebration collapses — new wine mourns, tabrets cease, and the city of confusion stands with every house shut up. A gleaning like olives shaken from a tree survives, singing for the majesty of the LORD. But fear, the pit, and the snare await the rest, and the earth reels like a drunkard, falling never to rise. At last the moon is confounded and the sun ashamed, for the LORD of hosts reigns in mount Zion before his ancients.",
    context:"A universal-judgment oracle in which the whole earth is emptied and defiled for breaking the everlasting covenant, closing with the LORD reigning in Zion.",
    keyVerses:[
      { ref:"Isaiah 24:5", text:"The earth also is defiled under the inhabitants thereof; because they have transgressed the laws, changed the ordinance, broken the everlasting covenant." },
      { ref:"Isaiah 24:20", text:"The earth shall reel to and fro like a drunkard, and shall be removed like a cottage; and the transgression thereof shall be heavy upon it; and it shall fall, and not rise again." },
      { ref:"Isaiah 24:23", text:"Then the moon shall be confounded, and the sun ashamed, when the LORD of hosts shall reign in mount Zion, and in Jerusalem, and before his ancients gloriously." }
    ],
    takeaway:"Breaking covenant with God unravels the whole earth; His reign in Zion is the end judgment points toward.",
    quiz:[
      { q:"In Isaiah 24, the earth is said to reel to and fro like what?", choices:["A rolling ship at anchor","A drunkard","A falling leaf","A spinning top"], a:3, why:"Verse 20 says the earth shall reel to and fro like a drunkard, and shall be removed like a cottage." },
      { q:"Why does the curse devour the earth in this chapter?", choices:["Because its inhabitants broke the everlasting covenant","Because Egypt refused to release Israel","Because the stars refused their light","Because Tyre hoarded her merchandise"], a:0, why:"Verses 5-6 give the reason: the people transgressed the laws and broken the everlasting covenant, therefore the curse devoured the earth." },
      { q:"What does the leveling of priest and people, buyer and seller, teach about the LORD's judgment?", choices:["Only rulers are held accountable","Status exempts no one from standing before God","Priests alone answer for the land","Judgment falls only on the poor"], a:1, why:"Verse 2 pairs every rank together — people with priest, servant with master — showing that no station escapes." }
    ] },
  { n:25, summary:"A song of praise answers the world's undoing: O LORD, thou art my God; thy counsels of old are faithfulness and truth. The LORD has made a fortified city a heap that will never be rebuilt, and strong peoples glorify him for it. He has been strength to the poor and needy, a refuge from the storm and a shadow from the heat, when the blast of the terrible ones beat like a storm against a wall. Then the chapter rises to its feast: in this mountain the LORD of hosts prepares for all people a feast of fat things and wines on the lees, destroys the covering and veil spread over all nations, swallows up death in victory, and wipes away tears from all faces. His waiting people rejoice: Lo, this is our God. Moab, meanwhile, is trodden down like straw for the dunghill.",
    context:"A song of praise after the earth's judgment, celebrating God's feast on Mount Zion, the defeat of death, and Moab's fall.",
    keyVerses:[
      { ref:"Isaiah 25:6", text:"And in this mountain shall the LORD of hosts make unto all people a feast of fat things, a feast of wines on the lees, of fat things full of marrow, of wines on the lees well refined." },
      { ref:"Isaiah 25:8", text:"He will swallow up death in victory; and the Lord GOD will wipe away tears from off all faces; and the rebuke of his people shall he take away from off all the earth: for the LORD hath spoken it." },
      { ref:"Isaiah 25:9", text:"And it shall be said in that day, Lo, this is our God; we have waited for him, and he will save us: this is the LORD; we have waited for him, we will be glad and rejoice in his salvation." }
    ],
    takeaway:"God prepares a feast where death is swallowed up in victory and every tear is wiped away.",
    quiz:[
      { q:"What does the LORD of hosts prepare in this mountain in Isaiah 25?", choices:["A banquet of hunger and thin broth","A feast of fat things and wines on the lees","A war council of the nations","A courtroom for the idols"], a:2, why:"Verse 6 promises a feast of fat things, of wines on the lees, of fat things full of marrow, for all people." },
      { q:"According to Isaiah 25:8, what will the Lord GOD do with death?", choices:["Postpone it for a generation","Exchange it for long life on earth","Leave it veiled from sight","Swallow it up in victory and wipe away tears from all faces"], a:3, why:"Verse 8 declares that he will swallow up death in victory and wipe away tears from off all faces." },
      { q:"What does this chapter show God has been for the poor and needy in distress?", choices:["A distant judge who waits for their perfection","A taskmaster who demands their tribute","A refuge from the storm and a shadow from the heat","An ally only for the strong"], a:0, why:"Verse 4 says thou hast been a strength to the poor, a refuge from the storm, a shadow from the heat." }
    ] },
  { n:26, summary:"In that day a song is sung in the land of Judah: we have a strong city, and God appoints salvation for walls and bulwarks. The righteous nation keeping truth enters its gates, and the LORD keeps in perfect peace the one whose mind is stayed on him. Trust ye in the LORD for ever, for in the LORD JEHOVAH is everlasting strength; the lofty city he lays low while the feet of the poor tread it down. The singers recall waiting for God in the night, desiring him with their soul, and learning righteousness through his judgments, though other lords once had dominion over them. Their labor felt like a woman crying in childbirth yet bringing forth wind. Then comes the great reversal: Thy dead men shall live — awake and sing, ye that dwell in dust — and God's people hide in their chambers a little moment until the indignation be overpast.",
    context:"Judah's future song of trust in the strong city, ending with the promise that the dead will rise and the faithful be hidden while indignation passes.",
    keyVerses:[
      { ref:"Isaiah 26:3", text:"Thou wilt keep him in perfect peace, whose mind is stayed on thee: because he trusteth in thee." },
      { ref:"Isaiah 26:19", text:"Thy dead men shall live, together with my dead body shall they arise. Awake and sing, ye that dwell in dust: for thy dew is as the dew of herbs, and the earth shall cast out the dead." },
      { ref:"Isaiah 26:20", text:"Come, my people, enter thou into thy chambers, and shut thy doors about thee: hide thyself as it were for a little moment, until the indignation be overpast." }
    ],
    takeaway:"Perfect peace belongs to the mind stayed on God, and death itself must awake and sing before Him.",
    quiz:[
      { q:"What does Isaiah 26 say God appoints for walls and bulwarks in the strong city?", choices:["Silver and gold","Angels","Watchmen with trumpets","Salvation"], a:1, why:"Verse 1 sings that salvation will God appoint for walls and bulwarks in the strong city." },
      { q:"What picture describes the people's failed efforts before God's intervention — laboring like a woman in childbirth who brings forth what?", choices:["A firstborn son","Wind","Twins","A nation of priests"], a:1, why:"Verses 17-18 liken their labor to a woman in pain who has, as it were, brought forth wind, working no deliverance." },
      { q:"What promise does Isaiah 26:19 give that anchors hope beyond the grave?", choices:["That the dead will be forgotten quietly","That the grave holds everyone forever","That only prophets escape death","Thy dead men shall live, and the earth shall cast out the dead"], a:3, why:"Verse 19 promises that the dead shall arise, awake and sing, for the earth shall cast out the dead." }
    ] },
  { n:27, summary:"The LORD takes up his sore and great and strong sword against leviathan the piercing serpent, even the dragon that is in the sea. Then the tone turns to a vineyard: sing of a vineyard of red wine, which the LORD himself keeps, watering it every moment, night and day, so that no one hurts it. Fury is not in him; if briers and thorns rise against him he burns them, but anyone may take hold of his strength and make peace. Jacob will take root, blossom and bud, and fill the face of the world with fruit; chastened in measure, his iniquity is purged as altar stones become chalkstones and images fall. The defenced city is left desolate for the calf to feed there, yet the LORD beats off his fruit one by one, and at the great trumpet the outcasts of Assyria and Egypt worship him in the holy mount.",
    context:"The LORD slays leviathan, keeps his vineyard Israel, purges Jacob's iniquity, and gathers his scattered people one by one at the great trumpet.",
    keyVerses:[
      { ref:"Isaiah 27:1", text:"In that day the LORD with his sore and great and strong sword shall punish leviathan the piercing serpent, even leviathan that crooked serpent; and he shall slay the dragon that is in the sea." },
      { ref:"Isaiah 27:3", text:"I the LORD do keep it; I will water it every moment: lest any hurt it, I will keep it night and day." },
      { ref:"Isaiah 27:13", text:"And it shall come to pass in that day, that the great trumpet shall be blown, and they shall come which were ready to perish in the land of Assyria, and the outcasts in the land of Egypt, and shall worship the LORD in the holy mount at Jerusalem." }
    ],
    takeaway:"The LORD keeps His vineyard night and day, and anyone may take hold of His strength and make peace.",
    quiz:[
      { q:"What sea monster does the LORD slay with his strong sword in Isaiah 27?", choices:["Leviathan the piercing serpent","Behemoth of the reeds","The whale of Joppa","The scorpion of the wilderness"], a:0, why:"Verse 1 names leviathan the piercing serpent, the crooked serpent, and the dragon that is in the sea." },
      { q:"In the vineyard song, why does no one need to fear for the vineyard's safety?", choices:["A wall of fire surrounds it","Its fruit is too bitter to steal","The LORD himself keeps and waters it every moment","Soldiers camp in it year-round"], a:2, why:"Verse 3 declares that the LORD keeps the vineyard, watering it every moment, night and day, lest any hurt it." },
      { q:"According to Isaiah 27:5, how can even one who resisted God find peace?", choices:["By outwaiting God's anger","By offering a larger sacrifice than ever","By paying tribute to the nations","By taking hold of God's strength and making peace with him"], a:3, why:"Verse 5 offers the alternative to burning briers: let him take hold of my strength, that he may make peace with me." }
    ] },
  { n:28, summary:"The crown of pride sits on drunk Ephraim's head as a fading flower on the head of the fat valleys, a hasty fruit eaten the moment it is seen. A mighty and strong one comes like a tempest of hail and a flood of overflowing waters to tread that crown under foot, while the LORD of hosts becomes a crown of glory and a diadem of beauty to the residue of his people. Priest and prophet alike stagger in vision and judgment through strong drink. Instruction comes precept upon precept, line upon line, here a little and there a little, offering rest — which they refuse. Jerusalem's scornful rulers boast a covenant with death and a refuge of lies, but the LORD lays in Zion a tried, precious corner stone, a sure foundation; judgment to the line and the plummet sweeps the lies away. A closing parable of the plowman shows that God, wonderful in counsel, teaches farmers their measured craft.",
    context:"A woe oracle against Ephraim's drunkards and Jerusalem's lying rulers, promising God's sure foundation stone in Zion and measured, farmer-like instruction.",
    keyVerses:[
      { ref:"Isaiah 28:10", text:"For precept must be upon precept, precept upon precept; line upon line, line upon line; here a little, and there a little:" },
      { ref:"Isaiah 28:15", text:"Because ye have said, We have made a covenant with death, and with hell are we at agreement; when the overflowing scourge shall pass through, it shall not come unto us: for we have made lies our refuge, and under falsehood have we hid ourselves:" },
      { ref:"Isaiah 28:16", text:"Therefore thus saith the Lord GOD, Behold, I lay in Zion for a foundation a stone, a tried stone, a precious corner stone, a sure foundation: he that believeth shall not make haste." }
    ],
    takeaway:"God teaches line upon line and lays a sure foundation; lies make a refuge too short to rest in.",
    quiz:[
      { q:"Whose drunkards wear the fading flower that Isaiah 28 calls the crown of pride?", choices:["Judah's","Ephraim's","Assyria's","Egypt's"], a:1, why:"Verse 1 cries woe to the crown of pride, to the drunkards of Ephraim, whose glorious beauty is a fading flower." },
      { q:"What does the LORD lay in Zion as the answer to a covenant with death?", choices:["A wall of bronze","A new set of sacrifices","A tower of watchmen","A tried stone, a precious corner stone, a sure foundation"], a:3, why:"Verse 16 promises the foundation stone in Zion; verse 18 says the covenant with death shall be disannulled." },
      { q:"What does the plowman parable at the chapter's end teach about how God deals with his people?", choices:["He punishes without instruction","He works with measured, fitting timing, as a farmer with each crop","He abandons fields that fail once","He expects harvest without sowing"], a:0, why:"Verses 24-29 show the farmer sowing each seed in its place and threshing gently, for his God doth instruct him to discretion." }
    ] },
  { n:29, summary:"Woe to Ariel, the city where David dwelt. The LORD will camp against her and lay siege until she is brought down and speaks low out of the dust, her voice like one with a familiar spirit whispering from the ground. Yet her besiegers, a multitude of strangers, will prove small dust and chaff, vanishing suddenly like a hungry man who wakes from a dream of eating still empty. The deeper trouble is within: the people are drunken without wine, a spirit of deep sleep covers prophets and seers, and every vision has become like the words of a book that is sealed. Because they honor God with their lips while their hearts are far from him, he will do a marvellous work and a wonder: the wisdom of their wise men shall perish. Then the deaf hear the words of the book, the blind see out of obscurity, the meek increase their joy, and Jacob's children sanctify the Holy One of Jacob.",
    context:"An oracle on Ariel (Jerusalem): siege and humiliation, an attacking multitude vanishing like a night dream, a sealed book, and God's marvellous work.",
    keyVerses:[
      { ref:"Isaiah 29:11", text:"And the vision of all is become unto you as the words of a book that is sealed, which men deliver to one that is learned, saying, Read this, I pray thee: and he saith, I cannot; for it is sealed:" },
      { ref:"Isaiah 29:13", text:"Wherefore the Lord said, Forasmuch as this people draw near me with their mouth, and with their lips do honour me, but have removed their heart far from me, and their fear toward me is taught by the precept of men:" },
      { ref:"Isaiah 29:14", text:"Therefore, behold, I will proceed to do a marvellous work among this people, even a marvellous work and a wonder: for the wisdom of their wise men shall perish, and the understanding of their prudent men shall be hid." }
    ],
    takeaway:"God is honored by hearts, not lips; His marvellous work turns worldly wisdom to dust and opens blinded eyes.",
    quiz:[
      { q:"By what name does Isaiah 29 call the city where David dwelt?", choices:["Zoan","Ariel","Hanes","Bozrah"], a:1, why:"Verse 1 opens, Woe to Ariel, to Ariel, the city where David dwelt." },
      { q:"What picture shows how suddenly the nations fighting Jerusalem will fail?", choices:["A hungry man who dreams of eating but wakes empty","A flood that dries up overnight","An army that forgets why it marched","A city gate that will not close"], a:0, why:"Verses 7-8 compare the attacking nations to a night vision, like a hungry or thirsty man who wakes from his dream unsatisfied." },
      { q:"Why does the LORD say he will do a marvellous work and a wonder?", choices:["Because the people's prophets were too numerous","Because foreign kings demanded a sign","Because the people drew near with their mouths while their hearts were far from him","Because the temple needed more offerings"], a:2, why:"Verses 13-14 connect the marvellous work to lip service without the heart, which brings the wisdom of their wise men to nothing." }
    ] },
  { n:30, summary:"Rebellious children take counsel, but not of the LORD, and walk down to Egypt, strengthening themselves in Pharaoh's shadow without asking at his mouth. Princes at Zoan and ambassadors at Hanes load beasts of the south with treasures for a people that cannot profit them; the Egyptians help in vain, for their strength is to sit still. The people are lying children who tell the seers, See not, and demand smooth things instead of right things. Their iniquity will break like a high wall, like a potter's vessel so shattered that no sherd remains. Yet the offer stands: in returning and rest shall ye be saved, in quietness and in confidence shall be your strength — and ye would not. Therefore the LORD waits to be gracious. Zion shall weep no more; a word behind them shall say, This is the way, walk ye in it; and through the voice of the LORD the Assyrian that smote with a rod is beaten down.",
    context:"A woe against Judah's embassy to Egypt for help against Assyria, contrasting Pharaoh's failing shadow with the LORD's offered rest.",
    keyVerses:[
      { ref:"Isaiah 30:15", text:"For thus saith the Lord GOD, the Holy One of Israel; In returning and rest shall ye be saved; in quietness and in confidence shall be your strength: and ye would not." },
      { ref:"Isaiah 30:21", text:"And thine ears shall hear a word behind thee, saying, This is the way, walk ye in it, when ye turn to the right hand, and when ye turn to the left." },
      { ref:"Isaiah 30:26", text:"Moreover the light of the moon shall be as the light of the sun, and the light of the sun shall be sevenfold, as the light of seven days, in the day that the LORD bindeth up the breach of his people, and healeth the stroke of their wound." }
    ],
    takeaway:"In returning and rest you are saved; in quietness and confidence God becomes your strength.",
    quiz:[
      { q:"Where do the rebellious children seek strength instead of asking at the LORD's mouth?", choices:["Babylon","Tyre","Damascus","Egypt"], a:3, why:"Verses 1-2 condemn those who walk to go down into Egypt, to strengthen themselves in the strength of Pharaoh." },
      { q:"How do the lying children want the prophets to preach?", choices:["Only in foreign languages","Speak unto us smooth things, prophesy deceits","Only at night gatherings","Only in written letters"], a:1, why:"Verse 10 records their demand to the seers: See not; and to the prophets, Prophesy not unto us right things, speak unto us smooth things." },
      { q:"What promise does Isaiah 30:21 give to the corrected and teachable?", choices:["That they will never face adversity","That their enemies will vanish overnight","A word behind thee, saying, This is the way, walk ye in it","That teachers will remain hidden"], a:2, why:"Verse 21 promises a directing word behind them at every turning, whether to the right hand or to the left." }
    ] },
  { n:31, summary:"A second woe falls on those who go down to Egypt for help, staying on horses and trusting chariots because they are many, while never looking to the Holy One of Israel. Isaiah reasons simply: the Egyptians are men, and not God; their horses are flesh, and not spirit. When the LORD stretches out his hand, helper and helped fall together. He will come down to fight for mount Zion as a lion unafraid of shepherds, and as birds flying he will defend and deliver Jerusalem, passing over to preserve it. The call is to turn back to him from whom Israel has deeply revolted; in that day every man casts away the idols of silver and gold his own hands made, and the Assyrian falls by a sword not of a mighty man, fleeing for fear of the ensign whose fire is in Zion.",
    context:"A brief woe against trusting Egyptian horses and chariots instead of the Holy One of Israel, who defends Jerusalem like flying birds.",
    keyVerses:[
      { ref:"Isaiah 31:1", text:"Woe to them that go down to Egypt for help; and stay on horses, and trust in chariots, because they are many; and in horsemen, because they are very strong; but they look not unto the Holy One of Israel, neither seek the LORD!" },
      { ref:"Isaiah 31:3", text:"Now the Egyptians are men, and not God; and their horses flesh, and not spirit. When the LORD shall stretch out his hand, both he that helpeth shall fall, and he that is holpen shall fall down, and they all shall fail together." },
      { ref:"Isaiah 31:5", text:"As birds flying, so will the LORD of hosts defend Jerusalem; defending also he will deliver it; and passing over he will preserve it." }
    ],
    takeaway:"Egyptians are men and horses are flesh; only the LORD who defends like birds never fails to deliver.",
    quiz:[
      { q:"What image describes how the LORD of hosts will defend Jerusalem in Isaiah 31?", choices:["As birds flying","As a fortress of iron","As a wall of flames","As a mother eagle's cry alone"], a:0, why:"Verse 5 says, As birds flying, so will the LORD of hosts defend Jerusalem; defending also he will deliver it." },
      { q:"Why is Egypt's help certain to fail, in the chapter's own reasoning?", choices:["Its soldiers are badly trained","The Egyptians are men and their horses are flesh, not God and spirit","Its army lacks horses","Its rivers flood every year"], a:1, why:"Verse 3 contrasts men and flesh with God and spirit, so helper and helped fall together when the LORD stretches out his hand." },
      { q:"What response does the chapter call for from deeply revolted Israel?", choices:["Build stronger alliances","Double their offerings","Fortify Jerusalem's walls","Turn unto him from whom the children of Israel have deeply revolted"], a:3, why:"Verse 6 calls, Turn ye unto him from whom the children of Israel have deeply revolted, and verse 7 adds casting away their idols." }
    ] },
  { n:32, summary:"A better day opens: a king shall reign in righteousness, and a man shall be as a hiding place from the wind, a covert from the tempest, rivers of water in a dry place, and the shadow of a great rock in a weary land. Under that reign dull eyes and deaf ears open, the rash heart understands, and stammering tongues speak plainly; no one calls the vile person liberal or the churl bountiful, for each is known by what he devises. Then Isaiah confronts the careless women at ease: the vintage shall fail, thorns and briers come up on the pleasant fields, and palaces become dens — until the spirit is poured on us from on high. Then the wilderness becomes a fruitful field; judgment and righteousness dwell there, the work of righteousness is peace, and my people dwell in peaceable habitations and quiet resting places.",
    context:"A promise of a righteous king who shields his people like a great rock in a weary land, followed by warning to careless women and hope in the outpoured spirit.",
    keyVerses:[
      { ref:"Isaiah 32:2", text:"And a man shall be as an hiding place from the wind, and a covert from the tempest; as rivers of water in a dry place, as the shadow of a great rock in a weary land." },
      { ref:"Isaiah 32:15", text:"Until the spirit be poured upon us from on high, and the wilderness be a fruitful field, and the fruitful field be counted for a forest." },
      { ref:"Isaiah 32:17", text:"And the work of righteousness shall be peace; and the effect of righteousness quietness and assurance for ever." }
    ],
    takeaway:"Righteousness works peace; where God's Spirit is poured out, wilderness becomes fruitful field.",
    quiz:[
      { q:"In Isaiah 32:2, the coming man is compared to the shadow of what?", choices:["A spreading oak","A city wall at noon","A great rock in a weary land","A tent in the wilderness"], a:2, why:"Verse 2 pictures him as the shadow of a great rock in a weary land, with rivers of water in a dry place." },
      { q:"What changes the wilderness into a fruitful field in this chapter?", choices:["A new irrigation law","The return of the vintage season","A treaty with a righteous nation","The spirit poured upon us from on high"], a:3, why:"Verse 15 dates the transformation until the spirit be poured upon us from on high, and the wilderness be a fruitful field." },
      { q:"According to Isaiah 32:17, what does the work of righteousness produce?", choices:["Peace, with quietness and assurance for ever","Wealth for the liberal","Silence from all enemies","Quick victories in battle"], a:0, why:"Verse 17 teaches that the work of righteousness shall be peace, and its effect quietness and assurance for ever." }
    ] },
  { n:33, summary:"The spoiler is warned: when you cease to spoil, you shall be spoiled. Against him the faithful pray, O LORD, be gracious unto us; be thou their arm every morning. At the lifting up of the LORD the nations flee, and Zion is filled with judgment and righteousness, while wisdom and knowledge become the stability of the times and the fear of the LORD the treasure. The valiant ones cry without, ambassadors of peace weep, highways lie waste, and Lebanon and Sharon mourn. Then God rises: his enemies conceive chaff and bring forth stubble, and sinners in Zion tremble, asking who among us shall dwell with the devouring fire. The answer: he that walks righteously, refuses oppression's gain and bribes, and shuts his eyes from evil — he dwells on high and sees the king in his beauty. Jerusalem becomes a quiet habitation whose stakes are never removed, for the LORD is judge, lawgiver, and king, and the inhabitant shall not say, I am sick.",
    context:"An oracle against the spoiler (Assyria) with Zion's prayer for grace, the question of who can dwell with devouring fire, and Jerusalem's secure future.",
    keyVerses:[
      { ref:"Isaiah 33:6", text:"And wisdom and knowledge shall be the stability of thy times, and strength of salvation: the fear of the LORD is his treasure." },
      { ref:"Isaiah 33:15", text:"He that walketh righteously, and speaketh uprightly; he that despiseth the gain of oppressions, that shaketh his hands from holding of bribes, that stoppeth his ears from hearing of blood, and shutteth his eyes from seeing evil;" },
      { ref:"Isaiah 33:22", text:"For the LORD is our judge, the LORD is our lawgiver, the LORD is our king; he will save us." }
    ],
    takeaway:"The fear of the LORD is our treasure; He is our judge, our lawgiver, our king — He will save us.",
    quiz:[
      { q:"What three offices does Isaiah 33 claim for the LORD?", choices:["Judge, lawgiver, and king","Farmer, vintner, and sower","Prophet, priest, and scribe","Captain, herald, and scribe"], a:0, why:"Verse 22 declares, the LORD is our judge, the LORD is our lawgiver, the LORD is our king; he will save us." },
      { q:"Who, according to the chapter, can dwell with the devouring fire and everlasting burnings?", choices:["Anyone who offers enough sacrifices","Only the priests of Zion","The nation that wins the war","He that walketh righteously and despiseth the gain of oppressions"], a:3, why:"Verses 14-16 answer the sinners' question with the one who walks righteously, refuses bribes, and shuts his eyes from evil." },
      { q:"What does Isaiah 33:6 name as the treasure that stabilizes the times?", choices:["Grain in the towers","A standing army at the gates","The fear of the LORD, with wisdom and knowledge","Treaties with strong neighbors"], a:2, why:"Verse 6 calls wisdom and knowledge the stability of thy times, and says the fear of the LORD is his treasure." }
    ] },
  { n:34, summary:"All nations are summoned to hear, for the LORD's indignation is upon them and their armies are delivered to slaughter — their slain cast out, the mountains melted with blood. The hosts of heaven dissolve; the heavens are rolled together as a scroll, and their host falls like leaves off a vine and figs from a fig tree. The LORD's sword, bathed in heaven, comes down in particular on Idumea, the people of his curse, for a great sacrifice at Bozrah. It is the day of the LORD's vengeance and the year of recompences for the controversy of Zion. Idumea's streams turn to pitch and her dust to brimstone, burning and unquenched, smoke going up for ever; cormorant, bittern, owl, and raven possess her ruins, thorns fill her palaces, and nobles are called to a kingdom where none answer. Seek ye out of the book of the LORD, and read: none of these shall fail.",
    context:"A judgment oracle summoning the nations to hear, centered on the LORD's vengeance for the controversy of Zion and desolation poured on Idumea.",
    keyVerses:[
      { ref:"Isaiah 34:4", text:"And all the host of heaven shall be dissolved, and the heavens shall be rolled together as a scroll: and all their host shall fall down, as the leaf falleth off from the vine, and as a falling fig from the fig tree." },
      { ref:"Isaiah 34:8", text:"For it is the day of the LORD's vengeance, and the year of recompences for the controversy of Zion." },
      { ref:"Isaiah 34:16", text:"Seek ye out of the book of the LORD, and read: no one of these shall fail, none shall want her mate: for my mouth it hath commanded, and his spirit it hath gathered them." }
    ],
    takeaway:"God keeps a record of judgment; seek out the book of the LORD and read — not one word fails.",
    quiz:[
      { q:"Which land does the LORD's sword come down upon in Isaiah 34?", choices:["Moab","Tyre","Egypt","Idumea"], a:3, why:"Verse 5 says the sword shall come down upon Idumea, and verse 6 names a great sacrifice in Bozrah, in the land of Idumea." },
      { q:"What picture in verse 4 shows the scale of the coming dissolution?", choices:["The heavens rolled together as a scroll","Rivers flowing backward to their sources","Stars marching in battle array","The sun standing still at noon"], a:0, why:"Verse 4 says the heavens shall be rolled together as a scroll, with their host falling like leaves and figs." },
      { q:"What confidence does 'seek ye out of the book of the LORD, and read' invite?", choices:["That no one can understand Isaiah","That judgment is only symbolic","That prophecy can be checked and trusted, for none of these shall fail","That history books matter more than prophets"], a:2, why:"Verse 16 invites readers to verify the prophecy in the book of the LORD, where no one of these shall fail." }
    ] },
  { n:35, summary:"The wilderness and the solitary place are told to be glad, and the desert to blossom as the rose, wearing the glory of Lebanon and the excellency of Carmel and Sharon. To fearful hearts comes the command: be strong, fear not; your God will come with vengeance and recompence, and he will save you. Then the body itself is renewed: blind eyes open, deaf ears are unstopped, the lame man leaps as a hart, and the tongue of the dumb sings, for waters break out in the wilderness and streams cross the desert, turning the parched ground to pools. A highway runs there, called The way of holiness, where the unclean cannot pass and wayfaring men, though fools, do not err; no lion prowls there, for the redeemed walk it. The ransomed of the LORD return to Zion with songs and everlasting joy, and sorrow and sighing flee away.",
    context:"A restoration poem in which the desert blossoms, the weakened body is healed, and the ransomed walk the way of holiness back to Zion with joy.",
    keyVerses:[
      { ref:"Isaiah 35:1", text:"The wilderness and the solitary place shall be glad for them; and the desert shall rejoice, and blossom as the rose." },
      { ref:"Isaiah 35:8", text:"And an highway shall be there, and a way, and it shall be called The way of holiness; the unclean shall not pass over it; but it shall be for those: the wayfaring men, though fools, shall not err therein." },
      { ref:"Isaiah 35:10", text:"And the ransomed of the LORD shall return, and come to Zion with songs and everlasting joy upon their heads: they shall obtain joy and gladness, and sorrow and sighing shall flee away." }
    ],
    takeaway:"Strengthen weak hands and feeble knees: your God is coming to save, and sorrow must flee His holy road.",
    quiz:[
      { q:"What is the highway in Isaiah 35 called?", choices:["The king's road","The way of holiness","The path of peace","The pilgrim's stair"], a:1, why:"Verse 8 names the highway The way of holiness, which the unclean shall not pass over." },
      { q:"What transformation happens to the parched ground when God comes to save?", choices:["It is sold to foreign farmers","It becomes a pool, with springs in the thirsty land","It is paved with precious stones","It is salted and left bare"], a:1, why:"Verses 6-7 promise waters breaking out in the wilderness and the parched ground becoming a pool." },
      { q:"What does this chapter say the redeemed will experience on the way to Zion?", choices:["Silence and sorrow without end","Tribute paid at every gate","Fear of lions along the road","Everlasting joy, with sorrow and sighing fleeing away"], a:3, why:"Verse 10 promises songs and everlasting joy upon their heads, with sorrow and sighing fleeing away; verse 9 adds that no lion shall be there." }
    ] },
  { n:36, summary:"In the fourteenth year of king Hezekiah, Sennacherib of Assyria takes all the defenced cities of Judah and sends Rabshakeh from Lachish, who stands by the conduit of the upper pool in the highway of the fuller's field. To Eliakim, Shebna, and Joah he hurls Hezekiah's reliance back at him: Egypt is a broken reed that pierces the hand that leans on it. He even claims the LORD's own commission — Go up against this land — and mocks the offer of two thousand horses no riders can be found for. Asked to speak in Syrian rather than the Jews' language, he cries out instead to the men on the wall: let not Hezekiah deceive you; make an agreement with me, and eat every one his vine and fig tree. Have any of the gods of the nations delivered their lands? The men hold their peace and answer not a word, by the king's commandment, then report to Hezekiah with their clothes rent.",
    context:"Assyria's field commander Rabshakeh taunts Jerusalem's officials and people in their own language, mocking trust in Egypt and in the LORD.",
    keyVerses:[
      { ref:"Isaiah 36:6", text:"Lo, thou trustest in the staff of this broken reed, on Egypt; whereon if a man lean, it will go into his hand, and pierce it: so is Pharaoh king of Egypt to all that trust in him." },
      { ref:"Isaiah 36:10", text:"And am I now come up without the LORD against this land to destroy it? the LORD said unto me, Go up against this land, and destroy it." },
      { ref:"Isaiah 36:21", text:"But they held their peace, and answered him not a word: for the king's commandment was, saying, Answer him not." }
    ],
    takeaway:"When faith is blasphemed, sometimes the strongest answer is silence before men and prayer before God.",
    quiz:[
      { q:"How many horses does Rabshakeh offer to give Hezekiah if he can set riders on them?", choices:["Two thousand","Seven hundred","Three hundred","Ten thousand"], a:0, why:"Verse 8 offers two thousand horses, if Hezekiah is able on his part to set riders upon them." },
      { q:"Why do Eliakim, Shebna, and Joah ask Rabshakeh to speak in the Syrian language?", choices:["Because they alone wanted to understand the terms","Because Syrian was the sacred tongue","So the men sitting on the wall would not hear his words","Because he requested a translator"], a:2, why:"Verse 11 asks him to speak in Syrian and not in the Jews' language, in the ears of the people that are on the wall." },
      { q:"What does the people's obedience to 'answer him not' model for believers facing mockery of God?", choices:["That mockery never matters","That silence before attackers can leave the matter with God","That every insult deserves a debate","That crowds should shout back"], a:1, why:"Verse 21 records that they held their peace and answered him not a word, by the king's commandment — the dispute moves to prayer in chapter 37." }
    ] },
  { n:37, summary:"Hezekiah rents his clothes and goes with sackcloth into the house of the LORD, sending to Isaiah: this is a day of trouble, rebuke, and blasphemy — the children are come to the birth, and there is not strength to bring forth. Isaiah answers that Sennacherib will hear a rumour, return, and fall by the sword in his own land. A second blasphemous letter arrives; Hezekiah spreads it before the LORD and prays that all the kingdoms may know that thou art the LORD, even thou only. The answer mocks the Assyrian's boasting — whom hast thou reproached? even the Holy One of Israel — and promises: he shall not come into this city, nor shoot an arrow there, for I will defend it for mine own sake, and for my servant David's sake. The angel of the LORD smites a hundred and fourscore and five thousand in the Assyrian camp; Sennacherib returns to Nineveh, where his own sons slay him in the house of Nisroch.",
    context:"Sennacherib's siege threats and letters against Jerusalem meet Hezekiah's prayer and Isaiah's prophecy; the angel of the LORD destroys the Assyrian army.",
    keyVerses:[
      { ref:"Isaiah 37:16", text:"O LORD of hosts, God of Israel, that dwellest between the cherubims, thou art the God, even thou alone, of all the kingdoms of the earth: thou hast made heaven and earth." },
      { ref:"Isaiah 37:35", text:"For I will defend this city to save it for mine own sake, and for my servant David's sake." },
      { ref:"Isaiah 37:36", text:"Then the angel of the LORD went forth, and smote in the camp of the Assyrians a hundred and fourscore and five thousand: and when they arose early in the morning, behold, they were all dead corpses." }
    ],
    takeaway:"Spread the threatening letter before the LORD; He defends His city and answers reproach against His name.",
    quiz:[
      { q:"How many Assyrians does the angel of the LORD smite in one night?", choices:["Five thousand","Eighteen hundred","Fourscore and seven","A hundred and fourscore and five thousand"], a:2, why:"Verse 36 says the angel smote a hundred and fourscore and five thousand — one hundred eighty-five thousand — in the Assyrian camp." },
      { q:"What does Hezekiah do with the letter from the Assyrian messengers?", choices:["Sends it back unread","Burns it in the temple court","Files it with the treaties","Spreads it before the LORD in the house of the LORD and prays"], a:3, why:"Verse 14 says Hezekiah went up unto the house of the LORD, and spread it before the LORD, then prayed." },
      { q:"What reason does the LORD give for defending Jerusalem from Sennacherib?", choices:["Judah's military strength","For mine own sake, and for my servant David's sake","A treaty with Ethiopia","The city's high walls"], a:1, why:"Verse 35 gives the double reason: for mine own sake, and for my servant David's sake." }
    ] },
  { n:38, summary:"Sick unto death, Hezekiah hears Isaiah bring the hard word: set thine house in order, for thou shalt die, and not live. The king turns his face to the wall, prays, and weeps sore, remembering that he walked before God in truth and with a perfect heart. The word returns: I have heard thy prayer, I have seen thy tears; I will add unto thy days fifteen years, and deliver thee and this city out of the hand of the king of Assyria. The sign is astonishing — the shadow on the sun dial of Ahaz goes backward ten degrees. Hezekiah's writing recalls his anguish: his age removed like a shepherd's tent, life cut off like a weaver's work, chattering like a crane or swallow, mourning as a dove. Then gratitude: thou hast in love to my soul delivered it from the pit of corruption, and cast all my sins behind thy back; the living shall praise thee, and a lump of figs laid on the boil brings recovery.",
    context:"Hezekiah's terminal illness meets prayer and tears; the LORD adds fifteen years and confirms it with the sun dial of Ahaz's shadow moving backward.",
    keyVerses:[
      { ref:"Isaiah 38:5", text:"Go, and say to Hezekiah, Thus saith the LORD, the God of David thy father, I have heard thy prayer, I have seen thy tears: behold, I will add unto thy days fifteen years." },
      { ref:"Isaiah 38:8", text:"Behold, I will bring again the shadow of the degrees, which is gone down in the sun dial of Ahaz, ten degrees backward. So the sun returned ten degrees, by which degrees it was gone down." },
      { ref:"Isaiah 38:17", text:"Behold, for peace I had great bitterness: but thou hast in love to my soul delivered it from the pit of corruption: for thou hast cast all my sins behind thy back." }
    ],
    takeaway:"The LORD hears prayer and sees tears; the living praise Him for delivering the soul from the pit.",
    quiz:[
      { q:"By how many degrees does the shadow return on the sun dial of Ahaz?", choices:["Three","Seven","Ten","Twelve"], a:2, why:"Verse 8 says the shadow of the degrees went down ten degrees, and the sun returned ten degrees backward." },
      { q:"What remedy does Isaiah prescribe for Hezekiah's boil?", choices:["Washing seven times in the pool","Bitter herbs for seven days","Rest and silence in the temple","A lump of figs laid on it as a plaster"], a:3, why:"Verse 21 records Isaiah's instruction: let them take a lump of figs, and lay it for a plaster upon the boil." },
      { q:"What does Hezekiah's recovery psalm teach about where praise belongs?", choices:["Only angels may praise God","Praise belongs in music alone","Praise should wait for perfect health","The living, the living, he shall praise thee"], a:3, why:"Verse 19 contrasts the silent grave with the living who praise God, as the father makes known his truth to the children." }
    ] },
  { n:39, summary:"At that time Merodach-baladan, the son of Baladan, king of Babylon, sends letters and a present to Hezekiah, having heard of his sickness and recovery. Hezekiah is glad of them and shows the envoys everything: the house of his precious things, silver, gold, spices, precious ointment, armour, and all his treasures — nothing in all his dominion is withheld. Isaiah confronts him with two questions — what said these men, and what have they seen? — then delivers the word of the LORD of hosts: the days come when all that is in thine house, and what thy fathers laid up, shall be carried to Babylon, and of thy sons shall they take eunuchs for the palace of the king of Babylon. Hezekiah accepts the sentence humbly: Good is the word of the LORD, for there shall be peace and truth in my days.",
    context:"Babylon's king sends congratulatory envoys after Hezekiah's recovery; Isaiah announces the future Babylonian captivity of treasure and royal sons.",
    keyVerses:[
      { ref:"Isaiah 39:2", text:"And Hezekiah was glad of them, and shewed them the house of his precious things, the silver, and the gold, and the spices, and the precious ointment, and all the house of his armour, and all that was found in his treasures: there was nothing in his house, nor in all his dominion, that Hezekiah shewed them not." },
      { ref:"Isaiah 39:6", text:"Behold, the days come, that all that is in thine house, and that which thy fathers have laid up in store until this day, shall be carried to Babylon: nothing shall be left, saith the LORD." },
      { ref:"Isaiah 39:8", text:"Then said Hezekiah to Isaiah, Good is the word of the LORD which thou hast spoken. He said moreover, For there shall be peace and truth in my days." }
    ],
    takeaway:"Good is the word of the LORD — receive God's correction with humility, even when it grieves.",
    quiz:[
      { q:"Which king sent letters and a present to Hezekiah after his recovery?", choices:["Merodach-baladan","Sennacherib","Tirhakah","Esar-haddon"], a:0, why:"Verse 1 names Merodach-baladan, the son of Baladan, king of Babylon, who heard of the sickness and recovery." },
      { q:"What does Isaiah reveal will follow from Hezekiah showing all his treasures?", choices:["Assyria will double its tribute","The temple will be enlarged","Nothing shall be left; all will be carried to Babylon","Babylon will become an ally"], a:2, why:"Verses 6-7 announce that treasure and even Hezekiah's sons will be carried off to the palace of the king of Babylon." },
      { q:"What does Hezekiah's reply — Good is the word of the LORD — model about receiving hard prophecy?", choices:["Denying the word that hurts","Bargaining for a better sentence","Blaming the prophet who brought it","Submitting to God's word with a peaceful heart"], a:3, why:"Verse 8 shows Hezekiah accepting the sentence, resting in peace and truth for his own days." }
    ] },
  { n:40, summary:"Comfort begins: comfort ye, comfort ye my people — Jerusalem's warfare is accomplished, her iniquity pardoned, and she has received double for all her sins. A voice cries in the wilderness to prepare the way of the LORD: every valley exalted, every mountain made low, until all flesh sees the glory of the LORD. All flesh is grass; the flower fadeth, but the word of our God shall stand for ever. Zion is sent up the high mountain to cry, Behold your God! — the Lord GOD comes with strong hand and feeds his flock like a shepherd, gathering lambs in his arm and gently leading those with young. Who measured the waters in the hollow of his hand? Nations are a drop of a bucket; he sits on the circle of the earth and calls the stars by name. The everlasting God fainteth not; they that wait upon the LORD renew their strength, mount up with wings as eagles, run and not be weary, walk and not faint.",
    context:"The opening of Isaiah's consolation: pardon announced to Jerusalem, a highway prepared in the wilderness, and the Creator who renews the weary.",
    keyVerses:[
      { ref:"Isaiah 40:1", text:"Comfort ye, comfort ye my people, saith your God." },
      { ref:"Isaiah 40:8", text:"The grass withereth, the flower fadeth: but the word of our God shall stand for ever." },
      { ref:"Isaiah 40:31", text:"But they that wait upon the LORD shall renew their strength; they shall mount up with wings as eagles; they shall run, and not be weary; and they shall walk, and not faint." }
    ],
    takeaway:"They that wait upon the LORD renew their strength — wings like eagles, running without weariness.",
    quiz:[
      { q:"With whose wings do they that wait upon the LORD mount up?", choices:["Doves","Sparrows","Eagles","Angels"], a:2, why:"Verse 31 says they shall mount up with wings as eagles; run, and not be weary; and walk, and not faint." },
      { q:"What contrast anchors the promise that God's word stands for ever?", choices:["Cities rising and falling","Rivers flooding and drying","Grass withering and flowers fading","Kings conquering and dying"], a:2, why:"Verses 6-8 contrast all flesh as grass and the flower that fadeth with the word of our God that shall stand for ever." },
      { q:"What does Isaiah 40 teach about where lasting strength comes from?", choices:["Waiting upon the LORD, who fainteth not and gives power to the faint","Resting more hours each day","Trusting in the strength of youth","Avoiding every hardship"], a:0, why:"Verses 28-31 contrast even the youths who faint with those who wait upon the LORD, since the everlasting God fainteth not." }
    ] },
  { n:41, summary:"The islands are called to silence before the LORD, who has raised up a righteous man from the east, called him to his foot, and given him nations and kings. While the ends of the earth tremble, idol-makers encourage one another, nailing their gods fast. Israel, by contrast, is God's servant, Jacob his chosen, the seed of Abraham his friend: fear thou not, for I am with thee; I will strengthen, help, and uphold thee with the right hand of my righteousness. Though called a worm Jacob, Israel becomes a new sharp threshing instrument having teeth, threshing mountains small, and the poor and needy find rivers opened in high places and fountains in the valleys, with cedar, myrtle, fir, and pine planted in the wilderness — that all may know the hand of the LORD hath done this. Then the courtroom: produce your cause, ye idols; shew what shall happen hereafter. They are of nothing, their works of nought, their molten images wind and confusion.",
    context:"A trial scene in which the LORD raises up a conqueror from the east, reassures servant Israel as Abraham's seed, and challenges the idols to predict the future.",
    keyVerses:[
      { ref:"Isaiah 41:10", text:"Fear thou not; for I am with thee: be not dismayed; for I am thy God: I will strengthen thee; yea, I will help thee; yea, I will uphold thee with the right hand of my righteousness." },
      { ref:"Isaiah 41:14", text:"Fear not, thou worm Jacob, and ye men of Israel; I will help thee, saith the LORD, and thy redeemer, the Holy One of Israel." },
      { ref:"Isaiah 41:18", text:"I will open rivers in high places, and fountains in the midst of the valleys: I will make the wilderness a pool of water, and the dry land springs of water." }
    ],
    takeaway:"Fear not, thou worm Jacob: God upholds His chosen with His righteous right hand and turns weakness into strength.",
    quiz:[
      { q:"What unlikely creature does the LORD call Jacob and the men of Israel in Isaiah 41:14?", choices:["A worm","A wild ass","A startled deer","A sleeping lion"], a:0, why:"Verse 14 addresses them as worm Jacob and ye men of Israel, promising help from the LORD their redeemer." },
      { q:"What does the image of Israel as a new sharp threshing instrument having teeth promise?", choices:["Sharper laws for the nation","Sharper swords for the army","A mill for grinding grain in the temple","That mountains — great obstacles — will be beaten small as chaff"], a:3, why:"Verse 15 promises thou shalt thresh the mountains, and beat them small, and shalt make the hills as chaff." },
      { q:"How does the LORD prove his Godhead in this chapter's trial of the idols?", choices:["By comparing temple sizes","By refusing to speak at all","By declaring things to come before they spring forth, which idols cannot do","By counting the stars out loud"], a:2, why:"Verses 21-23 challenge the idols to shew the former things and declare things for to come; they are of nothing, and their molten images are wind and confusion." }
    ] },
  { n:42, summary:"Behold my servant, whom I uphold; mine elect, in whom my soul delighteth — God puts his Spirit upon him, and he brings forth judgment to the Gentiles. His manner is quiet: he will not break a bruised reed or quench the smoking flax, and he will not fail until judgment is set in the earth. The LORD calls him in righteousness, a covenant of the people and a light of the Gentiles, to open blind eyes and bring prisoners out of the prison house; my glory will I not give to another. A new song rises from the ends of the earth as the LORD goes forth like a mighty man, and he leads the blind in ways they knew not, making darkness light, while idol-trusters turn back ashamed. Then a sorrowful turn: who is blind, but my servant? Israel is robbed and spoiled, snared in prison houses, and the fire of God's anger burned around him — yet he knew not, and laid it not to heart.",
    context:"The first Servant song: God's elect servant brings gentle justice as a light to the Gentiles, while blind servant Israel sits robbed in prison houses.",
    keyVerses:[
      { ref:"Isaiah 42:1", text:"Behold my servant, whom I uphold; mine elect, in whom my soul delighteth; I have put my spirit upon him: he shall bring forth judgment to the Gentiles." },
      { ref:"Isaiah 42:3", text:"A bruised reed shall he not break, and the smoking flax shall he not quench: he shall bring forth judgment unto truth." },
      { ref:"Isaiah 42:8", text:"I am the LORD: that is my name: and my glory will I not give to another, neither my praise to graven images." }
    ],
    takeaway:"God's servant will not break the bruised reed nor quench the smoking flax — He will not fail.",
    quiz:[
      { q:"What two fragile things will God's servant not break or quench?", choices:["A bruised reed and smoking flax","A cracked bow and frayed cord","A broken jar and dim lamp","A wilted vine and dry stalk"], a:0, why:"Verse 3 promises a bruised reed shall he not break, and the smoking flax shall he not quench." },
      { q:"For what two purposes does God give his servant as a covenant of the people?", choices:["To collect tribute and build walls","To judge Egypt and Assyria","To crown kings and raise armies","To open blind eyes and free prisoners sitting in darkness"], a:3, why:"Verse 6-7 gives the servant as a covenant of the people and a light of the Gentiles, to open the blind eyes and bring out the prisoners." },
      { q:"What warning does the ending give to those who see much but observe little?", choices:["They will be made rulers","They will inherit the isles","They will receive double honor","The fire of God's correction can burn around us, yet we fail to lay it to heart"], a:3, why:"Verse 25 says the fury of battle set him on fire round about, yet he knew not; and it burned him, yet he laid it not to heart." }
    ] },
  { n:43, summary:"Fear not: the LORD who created Jacob and formed Israel has redeemed thee, called thee by thy name, and thou art mine. When thou passest through the waters I will be with thee; rivers shall not overflow thee, and fire shall not kindle upon thee — for the Holy One of Israel, thy Saviour, gave Egypt for thy ransom. Sons and daughters are gathered from the four quarters: I will say to the north, Give up; and to the south, Keep not back. Israel is God's witness: before me there was no God formed, neither shall there be after me; beside me there is no saviour. The redeemer sends to Babylon for Israel's sake and promises a new thing — a way in the wilderness, rivers in the desert — for a people he formed to shew forth his praise. Yet thou hast wearied me with thy sins; still, I, even I, am he that blotteth out thy transgressions for mine own sake, and will not remember thy sins.",
    context:"A redemption oracle to formed-and-named Israel: passage through water and fire, gathering from north and south, the trial before the nations, and sins blotted out.",
    keyVerses:[
      { ref:"Isaiah 43:1", text:"But now thus saith the LORD that created thee, O Jacob, and he that formed thee, O Israel, Fear not: for I have redeemed thee, I have called thee by thy name; thou art mine." },
      { ref:"Isaiah 43:2", text:"When thou passest through the waters, I will be with thee; and through the rivers, they shall not overflow thee: when thou walkest through the fire, thou shalt not be burned; neither shall the flame kindle upon thee." },
      { ref:"Isaiah 43:11", text:"I, even I, am the LORD; and beside me there is no saviour." }
    ],
    takeaway:"Beside the LORD there is no saviour; He walks with His own through waters and fire, and blots out their sins.",
    quiz:[
      { q:"Complete the promise: when thou walkest through the fire, thou shalt not be — what?", choices:["Old; for the flame is far from thee","Burned; neither shall the flame kindle upon thee","Lost; for rivers hide thee","Silent; for the fire has no voice"], a:1, why:"Verse 2 promises thou shalt not be burned; neither shall the flame kindle upon thee, for the LORD is with thee." },
      { q:"What role does the LORD assign to Israel before the gathered nations?", choices:["My witnesses, and my servant whom I have chosen","Silent observers of the trial","Judges over the idols' fate","Guardians of the temple vessels"], a:0, why:"Verse 10 declares, Ye are my witnesses, saith the LORD, and my servant whom I have chosen, to know and believe that I am he." },
      { q:"What reason does the LORD give for blotting out transgressions?", choices:["Israel's many offerings","The sweet cane bought with money","Jacob's perfect record","For mine own sake — and he will not remember thy sins"], a:3, why:"Verse 25 says, I, even I, am he that blotteth out thy transgressions for mine own sake, and will not remember thy sins." }
    ] },
  { n:44, summary:"Jacob my servant and Jesurun, the chosen, are told not to fear, for the LORD will pour water on the thirsty and his spirit upon their seed, who spring up as willows by the water courses. I am the first, and I am the last; and beside me there is no God — I know not any. Then the chapter mocks the idol workshop: the smith grows hungry at his forge; the carpenter carves a god after the figure of a man; and one log is burned half for warmth and baked bread, while its residue is worshipped with the prayer, Deliver me; for thou art my god. None considers, Is there not a lie in my right hand? Against that folly stands grace: I have blotted out, as a thick cloud, thy transgressions; return unto me; for I have redeemed thee. It closes naming Cyrus, the LORD's shepherd, who shall perform all his pleasure as Jerusalem is built and the temple's foundation laid.",
    context:"An oracle assuring chosen Israel of the outpoured Spirit, ridiculing the idol-maker's illogic, promising sins blotted out, and naming Cyrus as the LORD's shepherd.",
    keyVerses:[
      { ref:"Isaiah 44:6", text:"Thus saith the LORD the King of Israel, and his redeemer the LORD of hosts; I am the first, and I am the last; and beside me there is no God." },
      { ref:"Isaiah 44:22", text:"I have blotted out, as a thick cloud, thy transgressions, and, as a cloud, thy sins: return unto me; for I have redeemed thee." },
      { ref:"Isaiah 44:28", text:"That saith of Cyrus, He is my shepherd, and shall perform all my pleasure: even saying to Jerusalem, Thou shalt be built; and to the temple, Thy foundation shall be laid." }
    ],
    takeaway:"Return unto me, for I have redeemed thee — the God who names Cyrus has blotted out thy sins like a cloud.",
    quiz:[
      { q:"Whom does the LORD call my shepherd in Isaiah 44:28?", choices:["David","Hezekiah","Jacob","Cyrus"], a:3, why:"Verse 28 says of Cyrus, He is my shepherd, and shall perform all my pleasure, decreeing Jerusalem rebuilt and the temple foundation laid." },
      { q:"What absurdity does the idol-maker's day expose about idolatry?", choices:["He sells his idols cheaper than grain","He forgets which god he carved","He burns half the log for fire and bread, then worships the rest as a god","He builds the shrine before the idol"], a:2, why:"Verses 15-17 describe warming himself, baking bread, and roasting roast with one part of the tree, then falling down to the residue and praying, Deliver me." },
      { q:"What invitation follows the promise that sins are blotted out like a thick cloud?", choices:["Bring more silver offerings","Return unto me; for I have redeemed thee","Wait silently in the gates","Send ambassadors to Babylon"], a:1, why:"Verse 22 pairs the blotting out of transgressions with the call, return unto me; for I have redeemed thee." }
    ] }
);
